// Input is a single Slack message event from the Slack Trigger, with
// candidates_per_job merged in by Workflow Config.
// Pull every LinkedIn job URL out of the text and emit one item per job.
// Returning an empty array is fine — downstream nodes simply don't run,
// which is how ordinary channel chatter costs nothing.

const out = [];
const seenThisRun = new Set();

for (const item of $input.all()) {
  const m = item.json || {};

  // Skip anything the bot posted (our own shortlist contains the job URL and
  // would otherwise re-trigger the workflow) and skip joins/edits/etc.
  if (m.bot_id || m.subtype) continue;

  let raw = String(m.text || '');
  raw = raw.replace(/<@[^>]+>/g, ' ');              // strip @mentions
  raw = raw.replace(/<([^|>]+)(\|[^>]*)?>/g, '$1'); // unwrap Slack's <url|label>

  const urls = raw.match(/https?:\/\/[^\s<>]*linkedin\.com\/jobs[^\s<>]*/gi) || [];

  // The trigger gives the channel as a plain ID string (resolveIds off).
  const channelId = typeof m.channel === 'string'
    ? m.channel
    : (m.channel && (m.channel.id || m.channel.value)) || m.channel_id || null;

  for (const url of urls) {
    // /jobs/view/4237171755  |  /jobs/view/slug-at-company-4237171755  |  ?currentJobId=4237171755
    const patterns = [
      /currentJobId=(\d{6,})/,
      /jobs\/view\/(?:[^\/?#\s]*?-)?(\d{6,})/
    ];

    let jobId = null;
    for (const p of patterns) {
      const mm = url.match(p);
      if (mm) { jobId = mm[1]; break; }
    }
    if (!jobId || seenThisRun.has(jobId)) continue;
    seenThisRun.add(jobId);

    out.push({
      json: {
        linkedin_job_id: jobId,
        job_url: url,
        slack_channel_id: channelId,
        slack_user_id: m.user || null,
        slack_message_ts: m.ts || null,
        slack_thread_ts: m.thread_ts || m.ts || null,
        candidates_per_job: Number(m.candidates_per_job) || 5
      }
    });
  }
}

return out;

// Coresignal search endpoints return a bare JSON array of IDs. The Coresignal node
// passes each array element through as its own item, so an ID arrives as a raw
// number in item.json. Normalise every plausible shape.
function collectIds(items) {
  const ids = [];
  for (const item of items) {
    const j = item.json;
    if (j === null || j === undefined) continue;
    if (typeof j === 'number' || typeof j === 'string') { ids.push(j); continue; }
    if (Array.isArray(j)) { ids.push(...j); continue; }
    if (Array.isArray(j.data)) { ids.push(...j.data); continue; }
    if (j.id !== undefined) { ids.push(j.id); continue; }
    const vals = Object.values(j);
    if (vals.length === 1 && (typeof vals[0] === 'number' || typeof vals[0] === 'string')) ids.push(vals[0]);
  }
  return ids.filter(v => v !== null && v !== undefined && v !== '');
}

const ids = collectIds($input.all());

// Batch size is 1, so this is the job currently being processed.
const ctx = $('Loop Over Job Listings').first().json;

if (ids.length === 0) {
  throw new Error('Coresignal has no multi-source job matching LinkedIn job ID ' + ctx.linkedin_job_id + '. It may be too new, or not indexed from that source.');
}

return [{ json: { coresignal_job_id: ids[0], match_count: ids.length, ...ctx } }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "job_titles": {
      "type": "array",
      "items": { "type": "string" },
      "description": "3-6 realistic current job titles a strong candidate would hold today. Plain titles only."
    },
    "must_have_skills": {
      "type": "array",
      "items": { "type": "string" },
      "description": "3-8 hard skills, tools or technologies explicitly required by the ad. Single terms, lowercase."
    },
    "nice_to_have_skills": {
      "type": "array",
      "items": { "type": "string" },
      "description": "0-8 preferred-but-optional skills."
    },
    "countries": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Full English country names where the candidate should be located, e.g. 'United States', 'Germany'. Empty array if the role is fully remote and location-agnostic."
    },
    "min_years_experience": {
      "type": "number",
      "description": "Minimum total years of professional experience. Use 0 if the ad implies entry level."
    },
    "seniority": {
      "type": "string",
      "description": "One of: Internship, Entry level, Associate, Mid-Senior level, Director, Executive"
    },
    "search_summary": {
      "type": "string",
      "description": "One sentence describing the ideal candidate."
    }
  },
  "required": ["job_titles", "must_have_skills", "nice_to_have_skills", "countries", "min_years_experience", "seniority", "search_summary"]
}

parameters.text:
=You are a technical recruiter turning a job ad into search filters for a people-search database.

JOB AD
Title: {{ $json.title }}
Company: {{ $json.company_name }}
Location: {{ $json.location }} ({{ $json.country }})
Seniority (as posted): {{ $json.seniority }}
Employment type: {{ $json.employment_type }}
Department: {{ $json.department }}
Remote allowed: {{ $json.accepts_remote }}

Description:
{{ String($json.description || '').slice(0, 12000) }}

RULES
- Base every filter on what the ad actually says. Do not invent requirements.
- job_titles must be titles people put on their own profile, not the ad's marketing headline.
- must_have_skills should be searchable single terms (e.g. "kubernetes", "python", "salesforce"), not sentences.
- If the ad gives no country and is fully remote, return an empty countries array.
- If the ad states a years-of-experience minimum, use it. Otherwise infer conservatively from seniority.

parameters.jsCode:
// Turn the AI-extracted filters into a Coresignal Multi-source Employee ES DSL query.
const raw = $input.first().json;
const f = raw.output || raw.data || raw;

const titles = (f.job_titles || []).filter(Boolean).slice(0, 6);
const must = (f.must_have_skills || []).filter(Boolean).slice(0, 8);
const nice = (f.nice_to_have_skills || []).filter(Boolean).slice(0, 8);
const countries = (f.countries || []).filter(Boolean);
const minMonths = Math.max(0, Math.round(Number(f.min_years_experience || 0) * 12));

if (titles.length === 0) {
  throw new Error('AI returned no job_titles — cannot build an employee search.');
}

// Hard filters
const filter = [
  { term: { is_deleted: 0 } },
  { term: { is_working: 1 } }
];
if (minMonths > 0) {
  filter.push({ range: { total_experience_duration_months: { gte: minMonths } } });
}
if (countries.length > 0) {
  filter.push({ terms: { location_country: countries } });
}

// At least one title variant must match the person's current role.
const titleShould = titles.map(t => ({ match_phrase: { active_experience_title: t } }));

// Skills only boost relevance. Must-haves are weighted higher than nice-to-haves.
const skillShould = [];
for (const s of must) {
  skillShould.push({ match: { inferred_skills: { query: s, operator: 'and', boost: 3 } } });
  skillShould.push({ match: { historical_skills: { query: s, operator: 'and', boost: 2 } } });
}
for (const s of nice) {
  skillShould.push({ match: { inferred_skills: { query: s, operator: 'and', boost: 1 } } });
}

const esQuery = {
  query: {
    bool: {
      filter,
      must: [{ bool: { should: titleShould, minimum_should_match: 1 } }],
      should: skillShould
    }
  },
  sort: ['_score']
};

const job = $('Retrieve Job Data from Coresignal').first().json;
const ctx = $('Extract Job ID').first().json;

return [{
  json: {
    es_query: esQuery,
    filters: f,
    job_title: job.title,
    job_company: job.company_name,
    job_location: job.location,
    job_url: ctx.job_url,
    slack_channel_id: ctx.slack_channel_id,
    slack_user_id: ctx.slack_user_id,
    candidates_per_job: ctx.candidates_per_job || 5
  }
}];

// Normalise the ID array and keep the top N (search returns best-scoring first).
function collectIds(items) {
  const ids = [];
  for (const item of items) {
    const j = item.json;
    if (j === null || j === undefined) continue;
    if (typeof j === 'number' || typeof j === 'string') { ids.push(j); continue; }
    if (Array.isArray(j)) { ids.push(...j); continue; }
    if (Array.isArray(j.data)) { ids.push(...j.data); continue; }
    if (j.id !== undefined) { ids.push(j.id); continue; }
    const vals = Object.values(j);
    if (vals.length === 1 && (typeof vals[0] === 'number' || typeof vals[0] === 'string')) ids.push(vals[0]);
  }
  return ids.filter(v => v !== null && v !== undefined && v !== '');
}

const ids = collectIds($input.all());
const wanted = Number($('Build Employee Search Query').first().json.candidates_per_job || 5);

if (ids.length === 0) {
  throw new Error('Employee search returned no matches. Loosen the filters (drop the country filter or the experience minimum).');
}

return ids.slice(0, wanted).map((id, i) => ({ json: { employee_id: id, rank: i + 1 } }));

// Build one Slack mrkdwn message: profile link, short description, skills,
// current title and the last 3 roles for each candidate.
const meta = $('Build Employee Search Query').first().json;

function truncate(s, n) {
  s = String(s || '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n - 1).trimEnd() + '…' : s;
}

function fmtDate(exp, which) {
  const y = exp[which + '_year'];
  const m = exp[which + '_month'];
  if (!y) return which === 'date_to' ? 'Present' : '?';
  return m ? String(m).padStart(2, '0') + '/' + y : String(y);
}

function lastThree(experience) {
  const list = Array.isArray(experience) ? experience.slice() : [];
  list.sort((a, b) => {
    const av = (a.date_from_year || 0) * 100 + (a.date_from_month || 0);
    const bv = (b.date_from_year || 0) * 100 + (b.date_from_month || 0);
    if (bv !== av) return bv - av;
    return (a.order_in_profile || 99) - (b.order_in_profile || 99);
  });
  return list.slice(0, 3);
}

const wanted = [
  ...(meta.filters?.must_have_skills || []),
  ...(meta.filters?.nice_to_have_skills || [])
].map(s => String(s).toLowerCase());

const blocks = [];
let rank = 0;

for (const item of $input.all()) {
  const p = item.json || {};
  rank += 1;

  const name = p.full_name || 'Unknown';
  const url = p.linkedin_url
    ? (p.linkedin_url.startsWith('http') ? p.linkedin_url : 'https://' + p.linkedin_url)
    : null;
  const title = p.active_experience_title || String(p.headline || '').split(' at ')[0] || '—';
  const location = p.location_full || p.location_country || '';
  const about = truncate(p.summary || p.headline || '', 260);

  // inferred_skills is a long, alphabetical, noisy list. Surface the ones that
  // actually match the job's requirements first, then pad with the rest.
  const all = (p.inferred_skills || []).map(s => String(s).toLowerCase());
  const matched = all.filter(s => wanted.some(w => s === w || s.includes(w) || w.includes(s)));
  const rest = all.filter(s => !matched.includes(s) && s.length > 3);
  const shown = [...new Set([...matched, ...rest])].slice(0, 12);
  const skills = shown.length
    ? shown.map(s => matched.includes(s) ? '*' + s + '*' : s).join(', ')
    : '—';

  const expLines = lastThree(p.experience).map(e =>
    '   • *' + (e.position_title || '—') + '* — ' + (e.company_name || '—') +
    ' (' + fmtDate(e, 'date_from') + ' → ' + (e.active_experience ? 'Present' : fmtDate(e, 'date_to')) + ')'
  );

  const lines = [];
  lines.push('*' + rank + '. ' + (url ? '<' + url + '|' + name + '>' : name) + '*');
  lines.push('   ' + title + (location ? ' · ' + location : ''));
  if (about) lines.push('   _' + about + '_');
  lines.push('   *Skills:* ' + skills);
  if (expLines.length) {
    lines.push('   *Experience:*');
    lines.push(expLines.join('\n'));
  }
  blocks.push(lines.join('\n'));
}

const header = [
  '<@' + meta.slack_user_id + '> *' + (meta.filters?.search_summary || 'Candidate shortlist') + '*',
  ':briefcase: <' + meta.job_url + '|' + (meta.job_title || 'Job ad') + '> · ' + (meta.job_company || '') + ' · ' + (meta.job_location || ''),
  ':mag: Titles: ' + (meta.filters?.job_titles || []).join(', '),
  ':wrench: Must-have skills: ' + (meta.filters?.must_have_skills || []).join(', '),
  ':round_pushpin: ' + ((meta.filters?.countries || []).join(', ') || 'Any location') + ' · ' + (meta.filters?.min_years_experience || 0) + '+ yrs · ' + (meta.filters?.seniority || '')
].join('\n');

return [{
  json: {
    slack_channel_id: meta.slack_channel_id,
    candidate_count: blocks.length,
    message: header + '\n\n' + blocks.join('\n\n')
  }
}];
